var registerUser = async (payload) => {
  const { name, password, phone, role = Role.CUSTOMER } = payload;
  const email = normalizeEmail(payload.email);
  if (![Role.CUSTOMER, Role.TECHNICIAN].includes(role)) {
    throw new AppError(httpStatus3.BAD_REQUEST, "Invalid registration role");
  }
  const existingUser = await prisma.user.findUnique({
    where: {
      email
    }
  });
  if (existingUser) {
    if (existingUser.status === UserStatus.BANNED) {
      throw new AppError(httpStatus3.FORBIDDEN, "User is blocked");
    }
    if (existingUser.status === UserStatus.INACTIVE) {
      throw new AppError(
        httpStatus3.BAD_REQUEST,
        "User account has been deleted"
      );
    }
    if (!existingUser.emailVerified) {
      throw new AppError(
        httpStatus3.CONFLICT,
        "Email already registered but not verified. Please verify your email."
      );
    }
    throw new AppError(
      httpStatus3.CONFLICT,
      "User with this email already exists"
    );
  }
  const hashedPassword = await hashPassword(password);
  const otp = generateOtp();
  const otpKey = `${REGISTRATION_OTP_PREFIX}${email}`;
  const registrationDataKey = `${REGISTRATION_DATA_PREFIX}${email}`;
  await redisClient.set(otpKey, otp, {
    expiration: {
      type: "EX",
      value: OTP_EXPIRATION_SECONDS
    }
  });
  const registrationData = {
    name,
    email,
    password: hashedPassword,
    phone,
    role
  };
  await redisClient.set(registrationDataKey, JSON.stringify(registrationData), {
    expiration: {
      type: "EX",
      value: OTP_EXPIRATION_SECONDS
    }
  });
  const templatePath = path3.join(
    process.cwd(),
    "src/app/templates/registration-user-otp.ejs"
  );
  const templateData = {
    name,
    email,
    otp,
    expirationMinutes: OTP_EXPIRATION_SECONDS / 60
  };
  const html = await ejs.renderFile(templatePath, templateData);
  await transporter.sendMail({
    from: config_default.email_sender,
    to: email,
    subject: "Verify Your Email",
    html
  });
  return {
    message: "Registration successful. Please check your email for the verification OTP."
  };
};
var verifyEmail = async (payload) => {
  const email = normalizeEmail(payload.email);
  const otp = payload.otp;
  const existingUser = await prisma.user.findUnique({
    where: {
      email
    }
  });
  if (existingUser) {
    if (existingUser.status === UserStatus.BANNED) {
      throw new AppError(httpStatus3.FORBIDDEN, "User is blocked");
    }
    if (existingUser.status === UserStatus.INACTIVE) {
      throw new AppError(
        httpStatus3.BAD_REQUEST,
        "User account has been deleted"
      );
    }
    if (existingUser.emailVerified) {
      throw new AppError(httpStatus3.BAD_REQUEST, "Email is already verified");
    }
  }
  const otpKey = `${REGISTRATION_OTP_PREFIX}${email}`;
  const redisOtp = await redisClient.get(otpKey);
  if (!redisOtp) {
    throw new AppError(httpStatus3.BAD_REQUEST, "OTP has expired or is invalid");
  }
  if (redisOtp !== otp) {
    throw new AppError(httpStatus3.BAD_REQUEST, "OTP does not match");
  }
  const registrationDataKey = `${REGISTRATION_DATA_PREFIX}${email}`;
  const redisRegistrationData = await redisClient.get(registrationDataKey);
  if (!redisRegistrationData) {
    throw new AppError(
      httpStatus3.BAD_REQUEST,
      "Registration session has expired. Please register again."
    );
  }
  const registrationData = JSON.parse(
    redisRegistrationData
  );
  const createdUser = await prisma.user.create({
    data: {
      name: registrationData.name,
      email: registrationData.email,
      password: registrationData.password,
      phone: registrationData.phone,
      role: registrationData.role ?? Role.CUSTOMER,
      status: UserStatus.ACTIVE,
      emailVerified: true,
      authProvider: AuthProvider.CREDENTIAL
    },
    omit: {
      password: true
    }
  });
  await redisClient.del([otpKey, registrationDataKey]);
  const templatePath = path3.join(
    process.cwd(),
    "src/app/templates/welcome-email.ejs"
  );
  try {
    const html = await ejs.renderFile(templatePath, {
      name: createdUser.name
    });
    await transporter.sendMail({
      from: config_default.email_sender,
      to: createdUser.email,
      subject: "Welcome to Field Service Management",
      html
    });
  } catch (error) {
    console.error("Welcome email failed:", error);
  }
  const tokens = generateTokens({
    id: createdUser.id,
    name: createdUser.name,
    email: createdUser.email,
    role: createdUser.role
  });
  return {
    user: createdUser,
    ...tokens
  };
};
