import httpStatus5 from "http-status";
var createService = async (payload) => {
  const existingService = await prisma.service.findUnique({
    where: {
      slug: payload.slug
    }
  });
  if (existingService) {
    throw new AppError(409, "A service with this slug already exists");
  }
  const service = await prisma.service.create({
    data: {
      title: payload.title,
      slug: payload.slug,
      description: payload.description,
      category: payload.category,
      price: new prismaNamespace_exports.Decimal(payload.price),
      duration: payload.duration,
      image: payload.image
    }
  });
  return service;
};
var getAllServices = async (query) => {
  const { search, category, isActive } = query;
  const page = Number(query.page) || 1;
  const limit = Number(query.limit) || 10;
  const skip = (page - 1) * limit;
  const where = {};
  if (search) {
    where.OR = [
      {
        title: {
          contains: search,
          mode: "insensitive"
        }
      },
      {
        description: {
          contains: search,
          mode: "insensitive"
        }
      }
    ];
  }
  if (category) {
    where.category = category;
  }
  if (isActive !== void 0) {
    where.isActive = isActive === "true";
  }
  const [services, total] = await prisma.$transaction([
    prisma.service.findMany({
      where,
      skip,
      take: limit,
      orderBy: {
        createdAt: "desc"
      }
    }),
    prisma.service.count({
      where
    })
  ]);
  return {
    meta: {
      page,
      limit,
      total,
      totalPages: Math.ceil(total / limit)
    },
    data: services
  };
};
var getServiceById = async (id) => {
  const service = await prisma.service.findUnique({
    where: {
      id
    }
  });
  if (!service) {
    throw new AppError(httpStatus5.NOT_FOUND, "Service not found");
  }
  return service;
};
var updateService = async (id, payload) => {
  const existingService = await prisma.service.findUnique({
    where: {
      id
    }
  });
  if (!existingService) {
    throw new AppError(httpStatus5.NOT_FOUND, "Service not found");
  }
  if (payload.slug) {
    const slugExists = await prisma.service.findFirst({
      where: {
        slug: payload.slug,
        NOT: {
          id
        }
      }
    });
    if (slugExists) {
      throw new AppError(
        httpStatus5.CONFLICT,
        "A service with this slug already exists"
      );
    }
  }
  const service = await prisma.service.update({
    where: {
      id
    },
    data: {
      ...payload.title !== void 0 && {
        title: payload.title
      },
      ...payload.slug !== void 0 && {
        slug: payload.slug
      },
      ...payload.description !== void 0 && {
        description: payload.description
      },
      ...payload.category !== void 0 && {
        category: payload.category
      },
      ...payload.price !== void 0 && {
        price: new prismaNamespace_exports.Decimal(payload.price)
      },
      ...payload.duration !== void 0 && {
        duration: payload.duration
      },
      ...payload.image !== void 0 && {
        image: payload.image
      },
      ...payload.isActive !== void 0 && {
        isActive: payload.isActive
      }
    }
  });
  return service;
};
var deleteService = async (id) => {
  const service = await prisma.service.findUnique({
    where: {
      id
    }
  });
  if (!service) {
    throw new AppError(httpStatus5.NOT_FOUND, "Service not found");
  }
  const updatedService = await prisma.service.update({
    where: {
      id
    },
    data: {
      isActive: false
    }
  });
  return updatedService;
};
var ServiceService = {
  createService,
  getAllServices,
  getServiceById,
  updateService,
  deleteService
};

