var createTechnicianProfile = async (userId, payload) => {
  const user = await prisma.user.findUnique({
    where: {
      id: userId
    }
  });
  if (!user) {
    throw new AppError(httpStatus8.NOT_FOUND, "User not found");
  }
  if (user.role !== "TECHNICIAN") {
    throw new AppError(
      httpStatus8.FORBIDDEN,
      "Only technicians can create technician profiles"
    );
  }
  const existingProfile = await prisma.technicianProfile.findUnique({
    where: {
      userId
    }
  });
  if (existingProfile) {
    throw new AppError(
      httpStatus8.CONFLICT,
      "Technician profile already exists"
    );
  }
  const profile = await prisma.technicianProfile.create({
    data: {
      userId,
      bio: payload.bio,
      experience: payload.experience,
      specialization: payload.specialization,
      hourlyRate: new prismaNamespace_exports.Decimal(payload.hourlyRate)
    },
    include: {
      user: {
        select: {
          id: true,
          name: true,
          email: true,
          phone: true,
          avatar: true
        }
      }
    }
  });
  return profile;
};
