var updateReview = async (reviewId, customerId, payload) => {
  const review = await prisma.review.findUnique({
    where: {
      id: reviewId
    }
  });
  if (!review) {
    throw new AppError(404, "Review not found");
  }
  if (review.customerId !== customerId) {
    throw new AppError(403, "You can only update your own review");
  }
  const updateData = {};
  if (payload.comment !== void 0) {
    updateData.comment = payload.comment;
  }
  if (payload.rating !== void 0) {
    const numericRating = Number(payload.rating);
    if (isNaN(numericRating) || numericRating < 1 || numericRating > 5) {
      throw new AppError(400, "Rating must be a number between 1 and 5");
    }
    updateData.rating = numericRating;
  }
  const updatedReview = await prisma.review.update({
    where: {
      id: reviewId
    },
    data: updateData,
    include: {
      customer: {
        select: {
          id: true,
          name: true,
          email: true
        }
      },
      technician: {
        include: {
          user: {
            select: {
              id: true,
              name: true
            }
          }
        }
      }
    }
  });
  return updatedReview;
};
